import { SiteNav } from '../components/SiteNav';

// Sprint 5B — public benchmark results page.
//
// Every number here comes from benchmark/results/*_results.json, generated by
// benchmark/run_benchmark.py and classified per benchmark/METHODOLOGY.md v1.0,
// which was written and approved before the first query ran.
//
// Nothing on this page is rounded in our favour, and the detectors that scored
// badly are shown at the same size as the ones that scored well.

const RUN_DATE = 'August 2026';
const VERSION = 'v0.9.1';
// The detector set the benchmark was RUN on. v0.10.0 ships 35; do not bump
// this until the benchmark is re-run against the new set.
const DETECTOR_COUNT = 33;

const REPO = 'https://github.com/mpingosystems/safesql';
const METHODOLOGY_URL = `${REPO}/blob/main/benchmark/METHODOLOGY.md`;
const RESULTS_URL = `${REPO}/tree/main/benchmark/results`;

interface Row {
  dataset: string;
  queries: string;
  tp: string;
  fp: string;
  fn: string;
  precision: string;
  recall: string;
  median: string;
  p95: string;
  combined?: boolean;
}

const ROWS: Row[] = [
  { dataset: 'Seeded defects', queries: '66', tp: '33', fp: '13', fn: '0', precision: '71.7%', recall: '100.0%', median: '0.820', p95: '3.461' },
  { dataset: 'Adversarial', queries: '20', tp: '9', fp: '0', fn: '1', precision: '100.0%', recall: '90.0%', median: '1.967', p95: '4.746' },
  { dataset: 'Spider dev', queries: '1,034', tp: '—', fp: '—', fn: '—', precision: 'n/a', recall: 'n/a', median: '0.606', p95: '1.880' },
  { dataset: 'BIRD dev', queries: '1,534', tp: '—', fp: '—', fn: '—', precision: 'n/a', recall: 'n/a', median: '0.741', p95: '2.139' },
  { dataset: 'COMBINED', queries: '2,654', tp: '42', fp: '13', fn: '1', precision: '76.4%', recall: '97.7%', median: '0.703', p95: '2.164', combined: true },
];

const STATS = [
  { value: '2,654', label: 'queries tested' },
  { value: '76.4%', label: 'precision (labelled suites)' },
  { value: '97.7%', label: 'recall (labelled suites)' },
  { value: '0.70 ms', label: 'median validation time' },
];

const RESOLVED = [
  {
    title: 'Case-sensitive identifier matching',
    body:
      'SELECT name FROM singer against a schema declaring singer(Name) reported HALLUCINATED_COLUMN, because identifiers were compared as raw strings. Unquoted SQL identifiers are case-insensitive, so this was incorrect by SQL semantics. Found by this benchmark and fixed: it removed 501 spurious findings — 429 on Spider, 72 on BIRD.',
  },
  {
    title: 'Filter-blind cardinality reasoning',
    body:
      'AGGREGATE_OVER_FANOUT_JOIN inferred fan-out from schema relationships without checking whether a join targets the joined table’s primary key — which can match at most one row and therefore cannot multiply. Found by this benchmark on three BIRD queries, verified against the real database, and fixed. All three findings are gone and no true positive was lost.',
  },
];

const LIMITATIONS = [
  {
    title: 'Fan-out through a CTE is not detected',
    body:
      'A query that joins inside a CTE and aggregates outside it scores 100/100 and produces no finding, even when the aggregate is genuinely inflated. This is the standard dbt staging-model shape, so it is a material gap rather than an edge case. It is the single false negative in the table above, and the reason the flagship detector’s recall is 50%. Fix planned.',
  },
  {
    title: 'Double-quoted literals under a PostgreSQL grammar',
    body:
      'All 200 remaining HALLUCINATED_COLUMN findings on Spider come from queries like WHERE Airline = "JetBlue Airways". SQLite reads double quotes as a string literal; PostgreSQL reads them as an identifier, so the parser sees a column that does not exist. This is an artifact of running SQLite benchmark SQL through a PostgreSQL grammar, not a detector defect — but the findings are counted in the Spider column rather than quietly dropped.',
  },
  {
    title: 'Two detectors still dominate the findings',
    body:
      'JOIN_MULTIPLICATION (149 on Spider, 544 on BIRD) and INNER_JOIN_NULL_EXCLUSION account for most remaining findings, and measured 12.5% and 14.3% precision respectively on the seeded suite. Both fire on any inner join to a nullable foreign key. Spider records no nullability at all, so every Spider foreign key is treated as nullable.',
  },
  {
    title: 'The flagship detector has one confirmed catch',
    body:
      'After the cardinality fix, AGGREGATE_OVER_FANOUT_JOIN produces exactly one finding across all 2,654 queries — the seeded query written to trigger it — at 100% precision. It is no longer wrong, but it has not yet been shown right on third-party SQL. Closing the CTE gap above is what would change that.',
  },
];

const AMBIGUOUS = [
  ['Deliberate CROSS JOIN (date spine)', 'False positive if it fires'],
  ['SELECT * inside a CTE or subquery', 'False positive if it fires — only a final projection counts'],
  ['INNER JOIN on a nullable FK, nulls intentionally excluded', 'False positive if it fires'],
  ['Missing WHERE on a reference table under 500 rows', 'False positive if it fires'],
  ['Fan-out JOIN correctly pre-aggregated in a CTE', 'True negative if it stays silent'],
];

const COMMANDS = `# Clone and run — no API key required
git clone ${REPO}
cd safesql && npm ci

python benchmark/run_benchmark.py --dataset seeded
python benchmark/run_benchmark.py --dataset adversarial
python benchmark/run_benchmark.py --dataset spider
python benchmark/run_benchmark.py --dataset bird

# Spider and BIRD datasets download separately — see benchmark/README
# To run against the hosted API instead of the local engine, add:
#   --api-key $SAFESQL_API_KEY   (Pro or above; a free key runs only 12 of 35)`;

const card: React.CSSProperties = {
  background: '#18181b',
  border: '1px solid #27272a',
  borderRadius: 10,
  padding: 18,
};

const th: React.CSSProperties = {
  textAlign: 'right',
  padding: '8px 10px',
  color: '#a1a1aa',
  fontSize: 12,
  fontWeight: 600,
  borderBottom: '1px solid #27272a',
  whiteSpace: 'nowrap',
};

const td: React.CSSProperties = {
  textAlign: 'right',
  padding: '8px 10px',
  fontSize: 13,
  borderBottom: '1px solid #1f1f23',
  whiteSpace: 'nowrap',
};

export function BenchmarkPage() {
  return (
    <div style={{ background: '#09090b', color: '#e4e4e7', minHeight: '100vh' }}>
      <SiteNav current="benchmark" />

      <div style={{ maxWidth: 900, margin: '0 auto', padding: '32px 32px 48px' }}>
        {/* ── Header ─────────────────────────────────────────────────────── */}
        <h1 style={{ fontSize: 30, margin: '0 0 8px' }}>SafeSQL Pro — Public Benchmark</h1>
        <p style={{ color: '#a1a1aa', fontSize: 15, lineHeight: 1.6, margin: '0 0 4px' }}>
          Publicly reproducible results across <strong style={{ color: '#e4e4e7' }}>2,654 SQL queries</strong> from
          four datasets. Run it yourself with the commands below — the harness, the corpora and the
          classification rules are all in the repository.
        </p>
        <p style={{ color: '#71717a', fontSize: 13, lineHeight: 1.6 }}>
          Reproducible, not independently verified: this benchmark was designed, run and reviewed by
          Mpingo Systems. The seeded and adversarial suites were written by the same people who wrote the
          detectors. Spider and BIRD are the external check.
        </p>

        {/* ── Summary stats ──────────────────────────────────────────────── */}
        <div
          style={{
            display: 'grid',
            gridTemplateColumns: 'repeat(auto-fit, minmax(170px, 1fr))',
            gap: 12,
            margin: '24px 0',
          }}
        >
          {STATS.map((s) => (
            <div key={s.label} style={{ ...card, textAlign: 'center' }}>
              <div style={{ fontSize: 26, fontWeight: 800, color: '#a78bfa' }}>{s.value}</div>
              <div style={{ color: '#a1a1aa', fontSize: 12, marginTop: 4 }}>{s.label}</div>
            </div>
          ))}
        </div>

        {/* ── Results table ──────────────────────────────────────────────── */}
        <h2 style={{ fontSize: 19, marginTop: 32 }}>Results by dataset</h2>
        <div style={{ overflowX: 'auto' }}>
          <table style={{ width: '100%', borderCollapse: 'collapse', minWidth: 720 }}>
            <thead>
              <tr>
                <th style={{ ...th, textAlign: 'left' }}>Dataset</th>
                <th style={th}>Queries</th>
                <th style={th}>TP</th>
                <th style={th}>FP</th>
                <th style={th}>FN</th>
                <th style={th}>Precision</th>
                <th style={th}>Recall</th>
                <th style={th}>Median ms</th>
                <th style={th}>p95 ms</th>
              </tr>
            </thead>
            <tbody>
              {ROWS.map((r) => (
                <tr key={r.dataset} style={r.combined ? { background: '#141417', fontWeight: 700 } : undefined}>
                  <td style={{ ...td, textAlign: 'left' }}>{r.dataset}</td>
                  <td style={td}>{r.queries}</td>
                  <td style={td}>{r.tp}</td>
                  <td style={td}>{r.fp}</td>
                  <td style={td}>{r.fn}</td>
                  <td style={td}>{r.precision}</td>
                  <td style={td}>{r.recall}</td>
                  <td style={td}>{r.median}</td>
                  <td style={td}>{r.p95}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
        <p style={{ color: '#71717a', fontSize: 12.5, lineHeight: 1.7, marginTop: 12 }}>
          Parse rate 2,651 / 2,654 (99.9%). 3,430 total findings.{' '}
          <strong style={{ color: '#a1a1aa' }}>Spider and BIRD show n/a for precision and recall</strong>{' '}
          because their gold SQL is presumed correct and no defects are labelled — a true positive or false
          negative cannot be defined against them, so they measure finding rate instead (Spider 75.3%, BIRD
          75.2% of queries produced at least one finding). Combined precision and recall therefore derive
          from the 86 labelled queries; runtimes derive from all 2,654. The adversarial row reflects two
          patterns reclassified after review as expected-behaviour-requiring-suppression; under the
          pre-registered rules as written it scored 75.0% precision, and combined precision was 68.9%.
        </p>

        {/* ── Flagship spotlight ─────────────────────────────────────────── */}
        <h2 style={{ fontSize: 19, marginTop: 36 }}>Spotlight: AGGREGATE_OVER_FANOUT_JOIN</h2>
        <div style={{ ...card, borderLeft: '3px solid #7c3aed' }}>
          <p style={{ color: '#d4d4d8', fontSize: 14, lineHeight: 1.65, margin: '0 0 14px' }}>
            Our flagship detector: the JOIN that silently inflates an aggregate before it reaches
            production. It is the reason the product exists, so it gets reported in full.
          </p>
          <div
            style={{
              display: 'grid',
              gridTemplateColumns: 'repeat(auto-fit, minmax(110px, 1fr))',
              gap: 10,
              margin: '0 0 14px',
            }}
          >
            {[
              { k: 'Total findings', v: '1' },
              { k: 'True positives', v: '1' },
              { k: 'False positives', v: '0' },
              { k: 'False negatives', v: '1' },
              { k: 'Precision', v: '100.0%' },
              { k: 'Recall', v: '50.0%' },
            ].map((x) => (
              <div key={x.k} style={{ background: '#0f0f11', borderRadius: 8, padding: '10px 8px', textAlign: 'center' }}>
                <div style={{ fontSize: 18, fontWeight: 700 }}>{x.v}</div>
                <div style={{ color: '#71717a', fontSize: 11, marginTop: 2 }}>{x.k}</div>
              </div>
            ))}
          </div>
          <p style={{ color: '#a1a1aa', fontSize: 13, lineHeight: 1.7, margin: 0 }}>
            Across 2,654 queries this detector produced one true positive — the seeded query written to
            trigger it — and three false positives, all on BIRD <code>financial</code> gold answers
            (<code>0132</code>, <code>0144</code>, <code>0179</code>). We executed those three against the
            real database: the gold SQL and a grain-corrected rewrite returned byte-identical results
            (AVG 149609.18048780487; AVG 2270.9429824561403; SUM 303276) with identical row counts, so no
            double-counting occurred. The <code>disp</code> table genuinely is one-to-many on{' '}
            <code>account</code>, but each query's predicate collapses it to a single row. The one false
            negative is a fan-out through a CTE that scored 100/100. See Known Limitations 2 and 3.
          </p>
        </div>

        {/* ── Known limitations ──────────────────────────────────────────── */}
        <h2 style={{ fontSize: 19, marginTop: 36 }}>Found by this benchmark, and fixed</h2>
        <p style={{ color: '#a1a1aa', fontSize: 13.5, lineHeight: 1.7 }}>
          Two detector defects were discovered by running these datasets. Both are fixed, and the table
          above reflects the post-fix engine. They are listed because the benchmark finding them is the
          point of running it.
        </p>
        {RESOLVED.map((l) => (
          <div key={l.title} style={{ ...card, marginBottom: 10, borderLeft: '3px solid #22c55e' }}>
            <h3 style={{ fontSize: 14.5, margin: '0 0 6px' }}>✓ {l.title}</h3>
            <p style={{ color: '#a1a1aa', fontSize: 13, lineHeight: 1.7, margin: 0 }}>{l.body}</p>
          </div>
        ))}

        <h2 style={{ fontSize: 19, marginTop: 36 }}>Known limitations</h2>
        {LIMITATIONS.map((l, i) => (
          <div key={l.title} style={{ ...card, marginBottom: 10 }}>
            <h3 style={{ fontSize: 14.5, margin: '0 0 6px' }}>
              {i + 1}. {l.title}
            </h3>
            <p style={{ color: '#a1a1aa', fontSize: 13, lineHeight: 1.7, margin: 0 }}>{l.body}</p>
          </div>
        ))}

        {/* ── Methodology ────────────────────────────────────────────────── */}
        <h2 style={{ fontSize: 19, marginTop: 36 }}>Methodology</h2>
        <p style={{ color: '#a1a1aa', fontSize: 13.5, lineHeight: 1.7 }}>
          Classification rules were written and fixed{' '}
          <strong style={{ color: '#e4e4e7' }}>before the first query ran</strong>, so they could not be
          tuned to the results. Full text:{' '}
          <a href={METHODOLOGY_URL} style={{ color: '#a78bfa' }}>
            benchmark/METHODOLOGY.md
          </a>{' '}
          · per-dataset summaries and the full human-review queues:{' '}
          <a href={RESULTS_URL} style={{ color: '#a78bfa' }}>
            benchmark/results
          </a>
          . The raw per-query JSON is regenerated by the commands below rather than
          committed.
        </p>
        <div style={{ ...card, marginBottom: 12 }}>
          <p style={{ color: '#d4d4d8', fontSize: 13, lineHeight: 1.8, margin: 0 }}>
            <strong>TP</strong> — the detector fires, the pattern is unintentional, and it would produce
            wrong results.
            <br />
            <strong>FP</strong> — the detector fires, but the pattern is intentional and correct.
            <br />
            <strong>FN</strong> — the detector does not fire when it should have.
            <br />
            <strong>TN</strong> — the detector does not fire, correctly.
            <br />
            <span style={{ color: '#a1a1aa' }}>
              Scored per (query, detector) pair. SYNTAX_ERROR and CUSTOM_RULE are excluded — a parse
              failure is not a detection, and custom rules are caller-supplied.
            </span>
          </p>
        </div>
        <div style={{ ...card }}>
          <h3 style={{ fontSize: 14, margin: '0 0 8px' }}>Ambiguous cases, decided in advance</h3>
          {AMBIGUOUS.map(([pattern, ruling]) => (
            <div key={pattern} style={{ display: 'flex', gap: 10, padding: '5px 0', fontSize: 12.5 }}>
              <span style={{ color: '#d4d4d8', flex: '1 1 60%' }}>{pattern}</span>
              <span style={{ color: '#a1a1aa', flex: '1 1 40%' }}>{ruling}</span>
            </div>
          ))}
        </div>

        {/* ── Reproduction ───────────────────────────────────────────────── */}
        <h2 style={{ fontSize: 19, marginTop: 36 }}>Reproduce it</h2>
        <pre
          style={{
            ...card,
            overflowX: 'auto',
            fontSize: 12.5,
            lineHeight: 1.65,
            color: '#d4d4d8',
            fontFamily: 'ui-monospace, SFMono-Regular, Menlo, monospace',
          }}
        >
          {COMMANDS}
        </pre>

        {/* ── Footer ─────────────────────────────────────────────────────── */}
        <div style={{ borderTop: '1px solid #27272a', marginTop: 32, paddingTop: 16 }}>
          <p style={{ color: '#a1a1aa', fontSize: 13, lineHeight: 1.7, margin: '0 0 10px' }}>
            <strong style={{ color: '#e4e4e7' }}>What these numbers mean.</strong> On the 86 queries with
            labelled ground truth, {DETECTOR_COUNT} detectors reached 76.4% precision and 97.7% recall, with
            13 false positives — all from two join detectors, none from the flagship. On 2,568
            expert-written queries from Spider and BIRD there is no labelled ground truth, so no false
            positive rate can be computed against them; 44% of Spider and 64% of BIRD queries produced at
            least one finding, and the limitations above explain most of that. Running these datasets found
            two real detector defects, both now fixed. We publish the detectors that scored badly alongside
            the ones that scored well.
          </p>
          <p style={{ color: '#71717a', fontSize: 12 }}>
            Benchmark run: {RUN_DATE} · SafeSQL Pro {VERSION} · {DETECTOR_COUNT} detectors · Spider dev
            (1,034 queries) and BIRD dev (1,534 queries) both included. Benchmark run on 33-detector
            version. Updated benchmark with 35 detectors in progress.
          </p>
        </div>
      </div>
    </div>
  );
}
